// I021/271 - Surface Capabilities and Characteristics
class Cat021I271 {
public:
    const uint8_t& poa() const { return poa_; }
    uint8_t& mutable_poa() { return poa_; }
    void set_poa(const uint8_t& v) { poa_ = v; }

    const uint8_t& cdti_s() const { return cdti_s_; }
    uint8_t& mutable_cdti_s() { return cdti_s_; }
    void set_cdti_s(const uint8_t& v) { cdti_s_ = v; }

    const uint8_t& b2_low() const { return b2_low_; }
    uint8_t& mutable_b2_low() { return b2_low_; }
    void set_b2_low(const uint8_t& v) { b2_low_ = v; }

    const uint8_t& ras() const { return ras_; }
    uint8_t& mutable_ras() { return ras_; }
    void set_ras(const uint8_t& v) { ras_ = v; }

    const uint8_t& ident() const { return ident_; }
    uint8_t& mutable_ident() { return ident_; }
    void set_ident(const uint8_t& v) { ident_ = v; }

    bool has_lw() const { return lw_.has_value(); }
    const uint8_t& lw() const { return lw_.value(); }
    uint8_t& mutable_lw() { if (!lw_) lw_.emplace(); return *lw_; }
    void set_lw(const uint8_t& v) { lw_ = v; }
    void clear_lw() { lw_.reset(); }

    bool operator==(const Cat021I271&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_bits(0, 2);
        w.write_bits(poa_, 1);
        w.write_bits(cdti_s_, 1);
        w.write_bits(b2_low_, 1);
        w.write_bits(ras_, 1);
        w.write_bits(ident_, 1);
        {
            bool fx_continue = false;
            if (lw_.has_value()) fx_continue = true;
            w.write_bits(fx_continue ? 1 : 0, 1);
            if (fx_continue) {
                w.write_bits(lw_.value_or(0), 4);
                w.write_bits(0, 3);
                w.write_bits(0, 1); // Terminal FX=0
            }
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat021I271> decode(conduit::io::BitReader& r) {
        Cat021I271 result;
        CONDUIT_TRY(r.skip_bits(2));
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("decode Cat021I271.poa"));
            result.poa_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("decode Cat021I271.cdti-s"));
            result.cdti_s_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("decode Cat021I271.b2-low"));
            result.b2_low_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("decode Cat021I271.ras"));
            result.ras_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_bits(1);
            if (!val) return std::unexpected(val.error().with_context("decode Cat021I271.ident"));
            result.ident_ = static_cast<uint8_t>(*val);
        }
        // FX extension
        {
            auto fx_bit = r.read_bits(1);
            if (!fx_bit) return std::unexpected(fx_bit.error());
            if (*fx_bit) {
                {
                    auto val = r.read_bits(4);
                    if (!val) return std::unexpected(val.error());
                    result.lw_ = static_cast<uint8_t>(*val);
                }
                CONDUIT_TRY(r.skip_bits(3));
                CONDUIT_TRY(r.skip_bits(1)); // Terminal FX=0
            }
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat021I271{"
            << "poa=" << +(poa_)
            << ", cdti-s=" << +(cdti_s_)
            << ", b2-low=" << +(b2_low_)
            << ", ras=" << +(ras_)
            << ", ident=" << +(ident_)
            << ", lw=" << (lw_.has_value() ? std::to_string(*lw_) : std::string("<none>"))
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    uint8_t poa_{};
    uint8_t cdti_s_{};
    uint8_t b2_low_{};
    uint8_t ras_{};
    uint8_t ident_{};
    std::optional<uint8_t> lw_;
};

