// I048/030 - Warning/Error Conditions and Target Classification
class Cat048I030 {
public:
    const uint8_t& we() const { return we_; }
    uint8_t& mutable_we() { return we_; }
    void set_we(const uint8_t& v) { we_ = v; }

    bool has_we1() const { return we1_.has_value(); }
    const uint8_t& we1() const { return we1_.value(); }
    uint8_t& mutable_we1() { if (!we1_) we1_.emplace(); return *we1_; }
    void set_we1(const uint8_t& v) { we1_ = v; }
    void clear_we1() { we1_.reset(); }

    bool has_we2() const { return we2_.has_value(); }
    const uint8_t& we2() const { return we2_.value(); }
    uint8_t& mutable_we2() { if (!we2_) we2_.emplace(); return *we2_; }
    void set_we2(const uint8_t& v) { we2_ = v; }
    void clear_we2() { we2_.reset(); }

    bool operator==(const Cat048I030&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_bits(we_, 7);
        {
            bool fx_continue = false;
            if (we1_.has_value()) fx_continue = true;
            if (we2_.has_value()) fx_continue = true;
            w.write_bits(fx_continue ? 1 : 0, 1);
            if (fx_continue) {
                w.write_bits(we1_.value_or(0), 7);
                {
                    bool fx_continue_1 = false;
                    if (we2_.has_value()) fx_continue_1 = true;
                    w.write_bits(fx_continue_1 ? 1 : 0, 1);
                    if (fx_continue_1) {
                        w.write_bits(we2_.value_or(0), 7);
                        w.write_bits(0, 1); // Terminal FX=0
                    }
                }
            }
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat048I030> decode(conduit::io::BitReader& r) {
        Cat048I030 result;
        {
            auto val = r.read_bits(7);
            if (!val) return std::unexpected(val.error().with_context("decode Cat048I030.we"));
            result.we_ = static_cast<uint8_t>(*val);
        }
        // FX extension
        {
            auto fx_bit = r.read_bits(1);
            if (!fx_bit) return std::unexpected(fx_bit.error());
            if (*fx_bit) {
                {
                    auto val = r.read_bits(7);
                    if (!val) return std::unexpected(val.error());
                    result.we1_ = static_cast<uint8_t>(*val);
                }
                // FX extension
                {
                    auto fx_bit_1 = r.read_bits(1);
                    if (!fx_bit_1) return std::unexpected(fx_bit_1.error());
                    if (*fx_bit_1) {
                        {
                            auto val = r.read_bits(7);
                            if (!val) return std::unexpected(val.error());
                            result.we2_ = static_cast<uint8_t>(*val);
                        }
                        CONDUIT_TRY(r.skip_bits(1)); // Terminal FX=0
                    }
                }
            }
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat048I030{"
            << "we=" << +(we_)
            << ", we1=" << (we1_.has_value() ? std::to_string(*we1_) : std::string("<none>"))
            << ", we2=" << (we2_.has_value() ? std::to_string(*we2_) : std::string("<none>"))
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    uint8_t we_{};
    std::optional<uint8_t> we1_;
    std::optional<uint8_t> we2_;
};

