        CONDUIT_TRY(encode_mode_s_service_cap(mssc_, w));
        CONDUIT_TRY(encode_alt_resolution(arc_, w));
        CONDUIT_TRY(encode_aircraft_id_cap(aic_, w));
        w.write_bits(b1a_, 1);
        w.write_bits(b1b_, 4);
        if (w.has_error()) return std::unexpected(w.error());
