// I253/025 - Data Destination Identifier and Local Data Destination ID
class Cat253I025 {
public:
    const uint8& rep() const { return rep_; }
    uint8& mutable_rep() { return rep_; }
    void set_rep(const uint8& v) { rep_ = v; }

    const std::vector<Cat253I025_destinationsElement>& destinations() const { return destinations_; }
    std::vector<Cat253I025_destinationsElement>& mutable_destinations() { return destinations_; }
    void set_destinations(const std::vector<Cat253I025_destinationsElement>& v) { destinations_ = v; }

    bool operator==(const Cat253I025&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_u8(static_cast<uint8>(destinations_.size()));
        for (const auto& elem : destinations_) {
            CONDUIT_TRY(elem.encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat253I025> decode(conduit::io::BitReader& r) {
        Cat253I025 result;
        {
            auto val = r.read_u8();
            if (!val) return std::unexpected(val.error().with_context("decode Cat253I025.rep"));
            result.rep_ = static_cast<uint8>(*val);
        }
        {
            auto count = static_cast<size_t>(result.rep_);
            if (count > static_cast<size_t>(INT32_MAX)) return std::unexpected(conduit::Error(conduit::ErrorCode::InvalidArgument, "decode Cat253I025.destinations: decoded count " + std::to_string(count) + " exceeds INT32_MAX").with_context("decode Cat253I025.destinations"));
            result.destinations_.reserve(count);
            for (size_t i = 0; i < count; i++) {
                auto elem = Cat253I025_destinationsElement::decode(r);
                if (!elem) return std::unexpected(elem.error().with_context("decode Cat253I025.destinations"));
                result.destinations_.push_back(std::move(*elem));
            }
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat253I025{"
            << "rep=" << +(rep_)
            << ", destinations=["
            ;
            for (size_t i = 0; i < destinations_.size(); ++i) {
                if (i > 0) oss << ", ";
                oss << destinations_[i].to_string();
            }
            oss << "]"
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    uint8 rep_{};
    std::vector<Cat253I025_destinationsElement> destinations_{};
};

