class Cat253I090_data_itemsElement {
public:
    const std::array<uint8_t, 16>& data() const { return data_; }
    std::array<uint8_t, 16>& mutable_data() { return data_; }
    void set_data(const std::array<uint8_t, 16>& v) { data_ = v; }

    bool operator==(const Cat253I090_data_itemsElement&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_bytes(std::span<const uint8_t>(data_.data(), data_.size()));
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat253I090_data_itemsElement> decode(conduit::io::BitReader& r) {
        Cat253I090_data_itemsElement result;
        {
            auto span = r.read_bytes(16);
            if (!span) return std::unexpected(span.error().with_context("decode data-itemsElement.data"));
            std::copy(span->begin(), span->end(), result.data_.begin());
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat253I090_data_itemsElement{"
            << "data=[bytes]"
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    std::array<uint8_t, 16> data_{};
};

// I253/090 - Application Data (not used, included for completeness)
class Cat253I090 {
public:
    const uint8& rep() const { return rep_; }
    uint8& mutable_rep() { return rep_; }
    void set_rep(const uint8& v) { rep_ = v; }

    const std::vector<Cat253I090_data_itemsElement>& data_items() const { return data_items_; }
    std::vector<Cat253I090_data_itemsElement>& mutable_data_items() { return data_items_; }
    void set_data_items(const std::vector<Cat253I090_data_itemsElement>& v) { data_items_ = v; }

    bool operator==(const Cat253I090&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_u8(static_cast<uint8>(data_items_.size()));
        for (const auto& elem : data_items_) {
            CONDUIT_TRY(elem.encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat253I090> decode(conduit::io::BitReader& r) {
        Cat253I090 result;
        {
            auto val = r.read_u8();
            if (!val) return std::unexpected(val.error().with_context("decode Cat253I090.rep"));
            result.rep_ = static_cast<uint8>(*val);
        }
        {
            auto count = static_cast<size_t>(result.rep_);
            if (count > static_cast<size_t>(INT32_MAX)) return std::unexpected(conduit::Error(conduit::ErrorCode::InvalidArgument, "decode Cat253I090.data-items: decoded count " + std::to_string(count) + " exceeds INT32_MAX").with_context("decode Cat253I090.data-items"));
            result.data_items_.reserve(count);
            for (size_t i = 0; i < count; i++) {
                auto elem = Cat253I090_data_itemsElement::decode(r);
                if (!elem) return std::unexpected(elem.error().with_context("decode Cat253I090.data-items"));
                result.data_items_.push_back(std::move(*elem));
            }
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat253I090{"
            << "rep=" << +(rep_)
            << ", data-items=["
            ;
            for (size_t i = 0; i < data_items_.size(); ++i) {
                if (i > 0) oss << ", ";
                oss << data_items_[i].to_string();
            }
            oss << "]"
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    uint8 rep_{};
    std::vector<Cat253I090_data_itemsElement> data_items_{};
};

